// Generates client/src/formats/challengetemplates.ts from newserv's Challenge
// Mode character templates (src/PlayerSubordinates.cc
// get_challenge_template_definition, the v3 / BB tables). newserv is MIT
// licensed; the generated file keeps the attribution.
//
// newserv took these from the client (PsoBB.exe: SendPacket0xDFSubcommand2
// indexes DAT_009af360 hunters, DAT_009b05a0 rangers, DAT_009ae1e0 forces by
// the template number * 0x10: level, item list, technique list). tests/cmode
// checks the shape. The item bytes and technique lists were compared with the
// exe's tables for all 48 templates (tests/cmode.test.ts keeps a sample).
//
// Run: node tools/gen-challenge-templates.ts [path/to/newserv]
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const repo = join(dirname(fileURLToPath(import.meta.url)), '..');
const newserv = process.argv[2] ?? process.env.NEWSERV ?? join(repo, 'vendor/newserv');
const src = readFileSync(join(newserv, 'src/PlayerSubordinates.cc'), 'utf8');

function table(name: string): string {
  const start = src.indexOf(`${name}{`);
  if (start < 0) throw new Error(`no ${name}`);
  const end = src.indexOf('\n  };', start);
  return src.slice(start, end);
}

interface Tpl {
  level: number;
  items: { equipped: boolean; data: string }[];
  techs: [number, number][];
}

function hex16(v: string): string {
  return v.replace(/^0x/i, '').padStart(16, '0').toUpperCase();
}

function parse(name: string): Tpl[] {
  // Some rows put the technique list on the following lines.
  const body = table(name).replace(/\n\s*(?=\}|\{\{)/g, ' ');
  const out: Tpl[] = [];
  for (const line of body.split('\n')) {
    const m = /^\s*\{(\d+),\s*\{(.*?\))\},\s*\{(.*)\}\},?\s*$/.exec(line);
    if (!m) continue;
    const items: Tpl['items'] = [];
    for (const im of m[2].matchAll(/v3_item\((true|false),\s*(0x[0-9A-Fa-f]+),\s*(0x[0-9A-Fa-f]+)\)/g)) {
      const first = hex16(im[2]);
      const second = hex16(im[3]);
      // newserv writes the tables in GC form: data2 of a mag is byte-swapped
      // there ("PSO GC byteswaps data2 even when the item is a mag",
      // ItemData.hh). PsoBB.exe holds the little-endian bytes; all 48 templates
      // were compared against the exe (data1, equipped flag, data2).
      const data2 = first.startsWith('02') ? second.slice(8).match(/../g)!.reverse().join('') : second.slice(8);
      items.push({ equipped: im[1] === 'true', data: first + second.slice(0, 8) + data2 });
    }
    const techs: [number, number][] = [];
    for (const tm of m[3].matchAll(/\{(0x[0-9A-Fa-f]+|\d+),\s*(\d+)\}/g)) techs.push([Number(tm[1]), Number(tm[2])]);
    out.push({ level: Number(m[1]), items, techs });
  }
  return out;
}

const lines: string[] = [];
lines.push('// GENERATED by tools/gen-challenge-templates.ts from newserv');
lines.push('// (src/PlayerSubordinates.cc get_challenge_template_definition, v3 / Blue Burst');
lines.push('// tables). newserv is MIT licensed, (c) Martin Michelsen.');
lines.push('//');
lines.push('// The Challenge Mode starting characters: set_cmode_char_template(n) replaces');
lines.push('// each player with the template of its class (hunters, rangers, forces), n in');
lines.push('// 0..15. level is the character level (0-based), items the inventory (data1');
lines.push('// bytes 0..11 then data2 bytes 0..3 as 32 hex digits, equipped flag), techs the');
lines.push('// technique levels (technique number, level 0-based).');
lines.push('');
lines.push('export interface ChallengeTemplateItem {');
lines.push('  equipped: boolean;');
lines.push('  data: string;');
lines.push('}');
lines.push('export interface ChallengeTemplate {');
lines.push('  level: number;');
lines.push('  items: ChallengeTemplateItem[];');
lines.push('  techs: [number, number][];');
lines.push('}');
lines.push('');
for (const [cls, name] of [['hunter', 'v3_hunter_templates'], ['ranger', 'v3_ranger_templates'], ['force', 'v3_force_templates']] as const) {
  const t = parse(name);
  if (t.length !== 16) throw new Error(`${name}: ${t.length} templates`);
  lines.push(`export const CHALLENGE_${cls.toUpperCase()}_TEMPLATES: ChallengeTemplate[] = [`);
  for (const x of t) {
    lines.push(`  { level: ${x.level}, items: [${x.items.map((i) => `{ equipped: ${i.equipped}, data: '${i.data}' }`).join(', ')}], techs: ${JSON.stringify(x.techs)} },`);
  }
  lines.push('];');
  lines.push('');
}
writeFileSync(join(repo, 'client/src/formats/challengetemplates.ts'), lines.join('\n'));
console.log('wrote client/src/formats/challengetemplates.ts');
